{
  "name": "postman-profile-{{suffix}}",
  "description": "Fake harness profile created by Postman",
  "harnessType": "Generic",
  "executable": "garrison-fake-harness",
  "promptDelivery": "Stdin",
  "systemPromptDelivery": "PrependToPrompt",
  "mcpConfigFormat": "None",
  "outputParser": "ClaudeStreamJson",
  "resultSource": "ParserFinalEvent",
  "successPolicy": "FinalEvent",
  "defaultTimeoutSeconds": 120,
  "killGraceSeconds": 2,
  "isolateHome": true,
  "arguments": [
    {
      "template": "--format"
    },
    {
      "template": "claude"
    }
  ],
  "successExitCodes": [
    0
  ],
  "probeArguments": [
    "--version"
  ],
  "sessionFormat": "postman-session-v1"
}

{
  "version": 2,
  "document": "apiVersion: garrison/v1
kind: Agent
metadata:
  name: postman-scratch-{{suffix}}
spec:
  displayName: Scratch
"
}

{
  "input": "Start a conversation from Postman",
  "startConversation": true,
  "wait": true,
  "waitSeconds": 60
}

{
  "input": "File space conversation from Postman",
  "startConversation": true,
  "wait": true,
  "waitSeconds": 60
}

{
  "name": "postman-pipeline-{{suffix}}",
  "description": "Two fake-harness stages with a review gate on the first",
  "stages": [
    {
      "name": "draft",
      "agentId": "{{agentId}}",
      "deploymentId": "{{deploymentId}}",
      "requiresReview": true,
      "maxRevisions": 1,
      "parameters": [
        {
          "name": "format",
          "value": "claude"
        }
      ]
    },
    {
      "name": "edit",
      "agentId": "{{agentId}}",
      "maxAttempts": 2,
      "outputCharLimit": 4000
    }
  ]
}

{
  "input": "Write release notes from Postman",
  "sampleOutputs": [
    "Sample draft from Postman"
  ]
}

{
  "nodeId": "{{nodeId}}",
  "epoch": {{leaseEpoch}},
  "events": [
    {
      "sequence": 1,
      "eventType": "Lifecycle",
      "timestampUtc": "{{$isoTimestamp}}",
      "text": "Started by Postman."
    },
    {
      "sequence": 2,
      "eventType": "AssistantText",
      "timestampUtc": "{{$isoTimestamp}}",
      "text": "Hello from the Postman node."
    },
    {
      "sequence": 3,
      "eventType": "Usage",
      "timestampUtc": "{{$isoTimestamp}}",
      "inputTokens": 5,
      "outputTokens": 6
    }
  ]
}

{
  "jsonrpc": "2.0",
  "id": 207,
  "method": "tools/call",
  "params": {
    "name": "garrison_apply_manifest",
    "arguments": {
      "tenantId": "{{tenantId}}",
      "manifest": "apiVersion: garrison/v1\nkind: Agent\nmetadata:\n  name: postman-mcp-dry-run\nspec:\n  description: Dry-run only.\n",
      "dryRun": true
    }
  }
}

{
  "agentId": "{{agentId}}",
  "name": "postman-dep-{{suffix}}",
  "harnessProfileId": "{{fakeProfileId}}",
  "parameters": [
    {
      "name": "format",
      "value": "claude"
    }
  ],
  "allowedRunOverrides": [
    {
      "name": "format",
      "validation": "Enum",
      "pattern": "claude,codex,mux"
    }
  ],
  "description": "Updated by Postman",
  "timeoutSeconds": 120,
  "approvalsEnabled": false,
  "approvalDefaultAction": "Deny",
  "approvalTimeoutSeconds": 120,
  "approvalTimeoutDecision": "Deny",
  "approvalRules": [
    {
      "action": "Allow",
      "pattern": "Bash(git status:*)",
      "description": "Read-only git status"
    },
    {
      "action": "Deny",
      "pattern": "Bash(rm:*)"
    }
  ]
}
